/**
 * `audio-qa.sh` — the measured audio floor (road-to-a-film-built-from-time 4.1).
 *
 * Every fixture is generated by ffmpeg in the test, so each expected value
 * follows from how the fixture was made rather than from a stored number:
 * a level set 20 dB lower must read about 20 LU lower; a track in antiphase
 * must lose most of itself in the mono fold; digital silence must read as
 * unmeasurable (null), never as a loudness of zero.
 */
import { spawnSync } from 'node:child_process';
import * as fs from 'node:fs';
import * as os from 'node:os';
import * as path from 'node:path';
import { fileURLToPath } from 'node:url';

import { afterAll, beforeAll, describe, expect, it } from 'vitest';

const REPO_ROOT = path.resolve(fileURLToPath(import.meta.url), '..', '..', '..');
const AUDIO_QA = path.join(REPO_ROOT, 'src', 'scripts', 'media', 'lib', 'audio-qa.sh');
const CAN_RUN =
    spawnSync('ffmpeg', ['-version']).status === 0 && spawnSync('ffprobe', ['-version']).status === 0;

interface Reading {
    duration: number;
    channels: number;
    integrated_lufs: number | null;
    true_peak_dbtp: number | null;
    lra: number | null;
    silence_spans: Array<{ start: number; end: number }>;
    mono_fold_loss_db: number | null;
}

let dir = '';
const gen = (name: string, args: readonly string[]): string => {
    const out = path.join(dir, name);
    const r = spawnSync('ffmpeg', ['-v', 'error', '-y', ...args, out]);
    if (r.status !== 0) throw new Error(`fixture ${name} failed: ${String(r.stderr)}`);
    return out;
};
const measure = (file: string): Reading => {
    const r = spawnSync('bash', [AUDIO_QA, file], { encoding: 'utf-8' });
    expect(r.status, r.stderr).toBe(0);
    return JSON.parse(r.stdout) as Reading;
};

describe.skipIf(!CAN_RUN)('audio-qa.sh', () => {
    beforeAll(() => {
        dir = fs.mkdtempSync(path.join(os.tmpdir(), 'audio-qa-'));
    });
    afterAll(() => fs.rmSync(dir, { recursive: true, force: true }));

    const sine = (name: string, gainDb: number, seconds = 8): string =>
        gen(name, ['-f', 'lavfi', '-i', `sine=frequency=440:duration=${String(seconds)}`, '-af', `volume=${String(gainDb)}dB`, '-ac', '2']);

    it('reads loudness that follows the gain the fixture was made with', () => {
        const loud = measure(sine('loud.wav', 0));
        const quiet = measure(sine('quiet.wav', -20));
        expect(loud.integrated_lufs).not.toBeNull();
        expect(quiet.integrated_lufs).not.toBeNull();
        expect((loud.integrated_lufs ?? 0) - (quiet.integrated_lufs ?? 0)).toBeCloseTo(20, 0);
        expect((loud.true_peak_dbtp ?? 0) - (quiet.true_peak_dbtp ?? 0)).toBeCloseTo(20, 0);
        expect(loud.channels).toBe(2);
        expect(loud.duration).toBeCloseTo(8, 1);
    });

    it('reports a near-full-scale track with its true peak close to 0 dBTP', () => {
        const hot = measure(sine('hot.wav', 17));
        expect(hot.true_peak_dbtp).not.toBeNull();
        expect(hot.true_peak_dbtp ?? -99).toBeGreaterThan(-6);
    });

    it('measures no loss for identical channels and a large loss for antiphase', () => {
        const same = measure(sine('same.wav', 0));
        const anti = measure(
            gen('anti.wav', ['-f', 'lavfi', '-i', 'sine=frequency=440:duration=8', '-af', 'pan=stereo|c0=c0|c1=-1*c0']),
        );
        expect(same.mono_fold_loss_db).toBeCloseTo(0, 0);
        expect(anti.mono_fold_loss_db ?? 0).toBeGreaterThan(20);
    });

    it('reads digital silence as unmeasurable and as one silent span', () => {
        const silent = measure(gen('silent.wav', ['-f', 'lavfi', '-i', 'anullsrc=r=48000:cl=stereo', '-t', '3']));
        expect(silent.integrated_lufs).toBeNull();
        expect(silent.true_peak_dbtp).toBeNull();
        expect(silent.lra).toBeNull();
        expect(silent.silence_spans).toHaveLength(1);
        expect(silent.silence_spans[0]?.end).toBeCloseTo(3, 1);
    });

    it('withholds a loudness range on a track too short to have one', () => {
        expect(measure(sine('short.wav', 0, 3)).lra).toBeNull();
    });

    it('exits 4 on a file with no audio stream and 2 on a missing file', () => {
        const video = gen('video.mp4', ['-f', 'lavfi', '-i', 'color=c=black:s=32x32:d=1', '-pix_fmt', 'yuv420p']);
        expect(spawnSync('bash', [AUDIO_QA, video]).status).toBe(4);
        expect(spawnSync('bash', [AUDIO_QA, path.join(dir, 'nope.wav')]).status).toBe(2);
    });
});
